//! Internal state-machine acceptance fixtures. No live native/browser/provider receipt is claimed.
async fn submission_fixture()->(PgConnection,Value,Value) {
    let(mut c,job)=packet_service_fixture().await;let packet=packet_create(&mut c,job,"fictional-submission-receipt",json!([])).await.unwrap();execution_running(&mut c).await;let mut config=browser_pref(&mut c,"application_queue_policy").await;config["policy"]["notify_submitted"]=json!(false);browser_save(&mut c,"application_queue_policy",config).await;
    sqlx::raw_sql("ALTER TABLE jobs ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT clock_timestamp();CREATE TABLE IF NOT EXISTS agent_policies(key varchar(20) PRIMARY KEY,version integer NOT NULL,preferences jsonb NOT NULL);DELETE FROM agent_policies").execute(&mut c).await.unwrap();
    let id=Uuid::new_v4();let profile=Uuid::new_v4();let binding=json!({"profile_binding_id":profile,"profile_version":2,"selection_version":1,"browser_session_id":Uuid::new_v4(),"window_id":10,"tab_id":50});let account=json!({"revision":5,"approved":true,"candidate_profile_id":packet["candidate_profile_id"],"profile_binding_id":profile,"account_sha256":"a".repeat(64)});browser_save(&mut c,"naukri_account_binding",account.clone()).await;browser_save(&mut c,"chr_selection",json!({"version":1,"profile_binding_id":profile})).await;
    let at:Value=sqlx::query_scalar("SELECT to_jsonb(clock_timestamp())").fetch_one(&mut c).await.unwrap();let until:Value=sqlx::query_scalar("SELECT to_jsonb(clock_timestamp()+interval '180 seconds')").fetch_one(&mut c).await.unwrap();
    let work=json!({"id":id,"platform":"naukri","requisition":"123456789012","url":"https://www.naukri.com/job-listings-fictional-123456789012","job_id":job,"packet_id":packet["id"],"packet_revision":2,"profile_version":packet["candidate_profile_version"],"candidate_profile_id":packet["candidate_profile_id"],"account_binding_revision":5,"account_sha256":"a".repeat(64),"account_observation":{"source":"profile_ui","work_id":id,"account_sha256":"a".repeat(64),"profile_document_id":"fictional-profile-document","observed_at":at,"binding":binding},"binding":binding,"title":"Rust Engineer","company":"Fictional Labs","stage":"VERIFYING","status":"executing","operation":"reconcile_application","revision":8,"policy_revision":162,"lease_token":Uuid::new_v4(),"lease_until":until,"available_at":at,"attempts":1,"admitted_actions":[{"id":Uuid::new_v4(),"fingerprint":"apply:initial","at":at}]});browser_save(&mut c,&format!("apply_work:{id}"),work.clone()).await;
    sqlx::query("UPDATE application_packets SET lifecycle_state='submitting',revision=2,approved_revision=NULL WHERE id=$1").bind(packet["id"].as_str().unwrap().parse::<Uuid>().unwrap()).execute(&mut c).await.unwrap();(c,work,account)
}
fn submission_report(document:&str)->Value {json!({"kind":"execution_observation","observed_url":automated_apply_agents::execution::submission::HISTORY_URL,"requisition":"123456789012","execution":{"state":"APPLICATION_SENT","document_id":document,"account_sha256":"a".repeat(64),"evidence_sha256":"b".repeat(64),"title":"Rust Engineer","company":"Fictional Labs"}})}
async fn submission_observe(c:&mut PgConnection,work:&Value,report:Value)->Result<Value>{let settings=packet_settings();let resumes=automated_apply_agents::private_resume::Settings::from_values(&host_values()).unwrap();let request=automated_apply_agents::execution::admission::Request{identity:work["id"].as_str().unwrap().parse().unwrap(),revision:work["revision"].as_i64().unwrap(),token:work["lease_token"].as_str().unwrap().parse().unwrap(),binding:&work["binding"]};automated_apply_agents::execution::submission::observe(c,request,report,automated_apply_agents::execution::admission::Services{packets:&settings,resumes:&resumes}).await}
async fn submission_reclaim(c:&mut PgConnection,work:&Value)->Value {let lease=automated_apply_agents::execution::queue::claim(c,"naukri",&work["binding"],Some(&["reconcile_application"])).await.unwrap().unwrap();let settings=packet_settings();let resumes=automated_apply_agents::private_resume::Settings::from_values(&host_values()).unwrap();let request=automated_apply_agents::execution::admission::Request{identity:lease["id"].as_str().unwrap().parse().unwrap(),revision:lease["revision"].as_i64().unwrap(),token:lease["lease_token"].as_str().unwrap().parse().unwrap(),binding:&lease["binding"]};automated_apply_agents::execution::admission::admit(c,request,automated_apply_agents::execution::admission::Services{packets:&settings,resumes:&resumes}).await.unwrap()}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_submission_requires_two_documents_then_atomically_saves_strict_receipt_and_actual_guarded_packet(){
    let(mut c,work,account)=submission_fixture().await;let first=submission_observe(&mut c,&work,submission_report("fictional-history-document-one")).await.unwrap();assert_eq!(first["reason"],"provider_history_reload_required");assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'naukri_worker_receipt:')").fetch_one(&mut c).await.unwrap(),0);let next=submission_reclaim(&mut c,&first).await;let before=browser_snapshot(&mut c).await;assert_eq!(submission_observe(&mut c,&next,submission_report("fictional-history-document-one")).await.unwrap_err(),Failure("independent_history_reload_required"));assert_eq!(browser_snapshot(&mut c).await,before);
    let confirmed=submission_observe(&mut c,&next,submission_report("fictional-history-document-two")).await.unwrap();assert_eq!(confirmed["stage"],"SUBMITTED_CONFIRMED");assert_eq!(confirmed["submission_mode"],"recurring_worker_ui");assert_eq!(confirmed["admitted_actions"],work["admitted_actions"]);let key="naukri_worker_receipt:123456789012";let receipt=browser_pref(&mut c,key).await;let at=chrono::DateTime::parse_from_rfc3339(receipt["observed_at"].as_str().unwrap()).unwrap().with_timezone(&chrono::Utc);assert!(automated_apply_agents::execution::receipts::first_worker_bound(key,&receipt,&confirmed,&account,at));
    let packet:Value=sqlx::query_scalar("SELECT to_jsonb(p) FROM application_packets p WHERE id=$1").bind(work["packet_id"].as_str().unwrap().parse::<Uuid>().unwrap()).fetch_one(&mut c).await.unwrap();assert_eq!(packet["revision"],3);assert_eq!(packet["lifecycle_state"],"provider_confirmed_submitted");assert_eq!(packet["tracking_state"],"applied_verified");assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_submission_evidence WHERE confirmation_source='naukri_status_ui' AND NOT human_confirmed").fetch_one(&mut c).await.unwrap(),1);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_events WHERE event_type='naukri_persistent_ui_confirmed' AND origin='local_worker'").fetch_one(&mut c).await.unwrap(),1);assert_eq!(submission_observe(&mut c,&next,submission_report("fictional-history-document-two")).await.unwrap_err(),Failure("queue_lease_lost"));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_submission_dropped_receipt_write_rolls_back_job_packet_evidence_and_work(){
    let(mut c,work,_)=submission_fixture().await;let first=submission_observe(&mut c,&work,submission_report("fictional-history-document-one")).await.unwrap();let next=submission_reclaim(&mut c,&first).await;let before=browser_snapshot(&mut c).await;let packet_id=work["packet_id"].as_str().unwrap().parse::<Uuid>().unwrap();let original:Value=sqlx::query_scalar("SELECT to_jsonb(p) FROM application_packets p WHERE id=$1").bind(packet_id).fetch_one(&mut c).await.unwrap();
    sqlx::raw_sql("CREATE FUNCTION fixture_receipt_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'naukri_worker_receipt:') THEN RETURN NULL; END IF; RETURN NEW; END $$; CREATE TRIGGER fixture_receipt_drop BEFORE INSERT ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_receipt_drop()").execute(&mut c).await.unwrap();assert_eq!(submission_observe(&mut c,&next,submission_report("fictional-history-document-two")).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);let actual:Value=sqlx::query_scalar("SELECT to_jsonb(p) FROM application_packets p WHERE id=$1").bind(packet_id).fetch_one(&mut c).await.unwrap();assert_eq!(actual,original);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_submission_evidence").fetch_one(&mut c).await.unwrap(),0);sqlx::raw_sql("DROP TRIGGER fixture_receipt_drop ON owner_preferences;DROP FUNCTION fixture_receipt_drop()").execute(&mut c).await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_submission_wrong_identity_or_failed_apply_keeps_quarantine_and_cannot_mint_receipt(){
    let(mut c,work,_)=submission_fixture().await;let before=browser_snapshot(&mut c).await;let mut wrong=submission_report("fictional-history-document-one");wrong["execution"]["company"]=json!("Different Fictional Employer");assert_eq!(submission_observe(&mut c,&work,wrong).await.unwrap_err(),Failure("provider_receipt_identity_changed"));assert_eq!(browser_snapshot(&mut c).await,before);let unknown=submission_observe(&mut c,&work,json!({"kind":"failed","reason":"fixture_connection_lost"})).await.unwrap();assert_eq!(unknown["status"],"unknown");assert_eq!(unknown["stage"],"SUBMISSION_UNKNOWN");assert_eq!(unknown["admitted_actions"],work["admitted_actions"]);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'naukri_worker_receipt:')").fetch_one(&mut c).await.unwrap(),0);
    automated_apply_agents::execution::submission::recover_unknown(&mut c,false).await.unwrap();let value=browser_pref(&mut c,&format!("apply_work:{}",work["id"].as_str().unwrap())).await;assert_eq!(value["operation"],"reconcile_application");assert_eq!(value["status"],"queued");assert_eq!(value["admitted_actions"],work["admitted_actions"]);assert_eq!(value["stage"],"SUBMISSION_UNKNOWN");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_submission_reconciliation_bound_or_stop_never_requeues_apply_or_refunds_history(){
    let(mut c,mut work,_)=submission_fixture().await;work["status"]=json!("unknown");work["stage"]=json!("SUBMISSION_UNKNOWN");work["reconciliation_attempts"]=json!(3);let key=format!("apply_work:{}",work["id"].as_str().unwrap());browser_save(&mut c,&key,work.clone()).await;automated_apply_agents::execution::submission::recover_unknown(&mut c,false).await.unwrap();assert_eq!(browser_pref(&mut c,&key).await,work);let mut config=browser_pref(&mut c,"application_queue_policy").await;config["state"]=json!("STOPPED");browser_save(&mut c,"application_queue_policy",config).await;work["reconciliation_attempts"]=json!(0);browser_save(&mut c,&key,work.clone()).await;automated_apply_agents::execution::submission::recover_unknown(&mut c,false).await.unwrap();assert_eq!(browser_pref(&mut c,&key).await,work);
}
